<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Auth extends MY_Controller {
 public function login(){if($this->input->method() === 'post'){ $user=$this->User_model->find_by_email($this->input->post('email',TRUE)); if($user && $user['role']==='customer' && $user['status']==='active' && password_verify($this->input->post('password'),$user['password_hash'])){$this->session->regenerate_id(TRUE);$this->session->set_userdata('user',array('id'=>$user['id'],'name'=>$user['first_name'].' '.$user['last_name'],'role'=>$user['role']));redirect('dashboard');}$data['error']='Incorrect email or password.';} $this->view('auth/login',isset($data)?$data:array(),'auth');}
 public function register(){if($this->input->method()==='post'){$this->form_validation->set_rules('email','Email','required|valid_email|is_unique[users.email]');$this->form_validation->set_rules('password','Password','required|min_length[8]');if($this->form_validation->run()){$id=$this->User_model->create(array('role'=>'customer','first_name'=>$this->input->post('first_name',TRUE),'last_name'=>$this->input->post('last_name',TRUE),'email'=>$this->input->post('email',TRUE),'password'=>$this->input->post('password'),'status'=>'pending'));$this->db->insert('accounts',array('user_id'=>$id,'account_number'=>'GC'.date('Y').str_pad($id,8,'0',STR_PAD_LEFT),'created_at'=>date('Y-m-d H:i:s')));$this->session->set_flashdata('success','Your account has been created. Please sign in.');redirect('login');}}$this->view('auth/register',array(),'auth');}
 public function forgot_password(){if($this->input->method()==='post'){$user=$this->User_model->find_by_email($this->input->post('email',TRUE));if($user){$token=bin2hex(random_bytes(32));$this->db->insert('password_resets',array('user_id'=>$user['id'],'token_hash'=>hash('sha256',$token),'expires_at'=>date('Y-m-d H:i:s',time()+3600),'created_at'=>date('Y-m-d H:i:s')));log_message('info','Password reset requested for user '.$user['id']);}$this->session->set_flashdata('success','If that email is registered, reset instructions will be sent shortly.');redirect('forgot-password');}$this->view('auth/forgot_password',array(),'auth');} public function logout(){$this->session->sess_destroy();redirect('login');}
}
